kea_config:
{
    "Dhcp4": {
        "valid-lifetime": 4000,
        "decline-probation-period": 600,
        "interfaces-config": {
            "interfaces": [
                "vtnet0_vlan40",
                "vtnet0_vlan50"
            ],
            "dhcp-socket-type": "raw",
            "service-sockets-max-retries": 5,
            "service-sockets-retry-wait-time": 5000
        },
        "lease-database": {
            "type": "memfile",
            "persist": true
        },
        "control-socket": {
            "socket-type": "unix",
            "socket-name": "\/var\/run\/kea\/kea4-ctrl-socket"
        },
        "loggers": [
            {
                "name": "kea-dhcp4",
                "output_options": [
                    {
                        "output": "syslog"
                    }
                ],
                "severity": "INFO"
            }
        ],
        "subnet4": [
            {
                "id": 1,
                "subnet": "192.168.40.0\/24",
                "next-server": "",
                "match-client-id": true,
                "option-data": [
                    {
                        "name": "domain-name-servers",
                        "data": "192.168.40.1"
                    },
                    {
                        "name": "routers",
                        "data": "192.168.40.1"
                    },
                    {
                        "name": "domain-name",
                        "data": "soc.local"
                    }
                ],
                "pools": [
                    {
                        "pool": "192.168.40.110 - 192.168.40.199"
                    }
                ],
                "reservations": [],
                "user-context": {
                    "uuid": "80ca2d54-368e-423a-9780-cec154701b93",
                    "description": "SOC VLAN40 Employee"
                }
            },
            {
                "id": 2,
                "subnet": "192.168.50.0\/24",
                "next-server": "",
                "match-client-id": true,
                "option-data": [
                    {
                        "name": "domain-name-servers",
                        "data": "192.168.50.1"
                    },
                    {
                        "name": "routers",
                        "data": "192.168.50.1"
                    },
                    {
                        "name": "domain-name",
                        "data": "soc.local"
                    }
                ],
                "pools": [
                    {
                        "pool": "192.168.50.110 - 192.168.50.199"
                    }
                ],
                "reservations": [],
                "user-context": {
                    "uuid": "85599f1a-6213-4d9f-8419-382acbdabb92",
                    "description": "SOC VLAN50 Guest"
                }
            }
        ],
        "hooks-libraries": [
            {
                "library": "\/usr\/local\/lib\/kea\/hooks\/libdhcp_lease_cmds.so"
            },
            {
                "library": "\/usr\/local\/lib\/kea\/hooks\/libdhcp_host_cmds.so"
            }
        ]
    }
}
